import React from 'react';
import styled from 'styled-components';
import { theme } from 'twin.macro';
import { useTranslations } from 'next-intl';

const HowItWorksSectionContainer = styled.div`
    & > h2 {
        text-transform: uppercase;
        font-family: Quicksand;
        font-style: normal;
        font-weight: bold;
        text-align: center;

        font-size: 32px;
        line-height: 40px;

        margin-top: 64px;
        margin-bottom: 58px;

        @media (min-width: 1024px) {
            font-size: 48px;
            line-height: 60px;

            margin-top: 96px;
            margin-bottom: 58px;
        }
    }
`;

const BlocksDiv = styled.div`
    color: ${theme`colors.primary.dark`};

    min-height: 400px;

    display: flex;
    flex-wrap: wrap;
    justify-content: space-around;

    @media (min-width: 1024px) {
        justify-content: space-around;
    }
`;

const Block_1 = styled.div`
    display: flex;
    flex-direction: column;
    flex-wrap: wrap;
    justify-content: flex-start;
    align-items: center;

    width: 360px;
    height: 400px;

    @media (min-width: 1024px) {
        width: 360px;
    }

    svg {
        height: 200px;
    }

    div {
        height: 200px;

        text-align: center;

        position: relative;
        top: 36px;

        h2,
        h3 {
            font-family: 'Quicksand';
            font-weight: bold;
            text-transform: uppercase;
        }
        h2 {
            font-size: 50px;
            line-height: 62px;
        }
        h3 {
            font-size: 34px;
            line-height: 42px;
        }
        p {
            font-weight: bold;
            font-size: 16px;
            line-height: 22px;
        }
    }
`;

